@@ -1,4 +1,12 @@
 export function normalizeRepoPath(value) {
-  const normalized = value.replaceAll('\\', '/').replace(/^\/+/, '');
+  if (typeof value !== 'string') throw new Error('Invalid repo path');
+  const slashNormalized = value.replaceAll('\\', '/');
+  if (slashNormalized.startsWith('/') || /^[A-Za-z]:\//.test(slashNormalized)) {
+    throw new Error('Absolute paths are not allowed');
+  }
+  const normalized = slashNormalized.replace(/^\/+/, '');
+  if (normalized.split('/').some((segment) => segment === '..')) {
+    throw new Error('Parent directory segments are not allowed');
+  }
   return normalized;
 }

